import { apiClient } from './client'; import type { HospitalLoginRequest,HospitalLoginResponse,HospitalUser,Hospital,HospitalStaff } from '../types/models'; export const authApi={login:async(p:HospitalLoginRequest)=>(await apiClient.post<HospitalLoginResponse>('/hospital/auth/login',p)).data,me:async()=>{const{data}=await apiClient.get<{user:HospitalUser;hospital:Hospital;staff:HospitalStaff}>('/hospital/auth/me');return data}}
